const $ = (s,root=document)=>root.querySelector(s);
const $$ = (s,root=document)=>[...root.querySelectorAll(s)];
const esc = v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const current = location.pathname.split('/').pop() || 'index.html';
const page = current.replace('.html','');
const portrait = (a,cls='')=>`<div class="portrait ${cls}" style="--px:${a.x};--py:${a.y}" role="img" aria-label="AI-generated placeholder portrait for fictional artist ${a.name}"></div>`;
function card(a,i){return `<a class="artist-card" href="artist.html?id=${a.id}" aria-label="Discover ${a.name}"><div class="portrait-frame" data-scene="artist-portal">${portrait(a)}<span class="portrait-tag">FICTIONAL ARTIST</span><span class="portrait-arrow" aria-hidden="true">↗</span></div><div class="artist-meta"><div><h3>${a.name}</h3><p>${a.genre} / ${a.extra}</p></div><span class="artist-index">[0${i+1}]</span></div></a>`}
function drawArrowIcons(root=document){
  const paths={'\u2197':'M5 19 19 5M5 5h14v14','\u2190':'M19 12H5m7-7-7 7 7 7','\u2192':'M5 12h14m-7-7 7 7-7 7','\u2193':'M12 5v14m-7-7 7 7 7-7'};
  const walker=document.createTreeWalker(root,NodeFilter.SHOW_TEXT);const nodes=[];
  while(walker.nextNode())if(/[\u2197\u2190\u2192\u2193]/.test(walker.currentNode.textContent))nodes.push(walker.currentNode);
  for(const node of nodes){const fragment=document.createDocumentFragment();for(const part of node.textContent.split(/([\u2197\u2190\u2192\u2193])/)){if(paths[part]){const svg=document.createElementNS('http://www.w3.org/2000/svg','svg');svg.setAttribute('viewBox','0 0 24 24');svg.setAttribute('class','icon-arrow');svg.setAttribute('aria-hidden','true');svg.setAttribute('focusable','false');const path=document.createElementNS(svg.namespaceURI,'path');path.setAttribute('d',paths[part]);svg.append(path);fragment.append(svg)}else fragment.append(document.createTextNode(part))}node.replaceWith(fragment)}
}
function sculpture(){let rings='';for(let i=0;i<39;i++){const angle=i*4.615;const rx=110+Math.sin(i/38*Math.PI)*43;const ry=158+Math.cos(i/38*Math.PI)*15;rings+=`<ellipse cx="250" cy="250" rx="${rx}" ry="${ry}" transform="rotate(${angle} 250 250)" fill="none" stroke="url(#chrome)" stroke-width="${i%4===0?2.6:1.65}" opacity="${.4+i/65}"/>`;}return `<div class="sculpture" data-scene="hero-sculpture" aria-hidden="true"><svg viewBox="0 0 500 500"><defs><linearGradient id="chrome" x1="0" y1="0" x2="1" y2=".8"><stop stop-color="#1b1d17"/><stop offset=".2" stop-color="#b4b8a8"/><stop offset=".35" stop-color="#f0f1e9"/><stop offset=".48" stop-color="#555c49"/><stop offset=".63" stop-color="#10120d"/><stop offset=".78" stop-color="#c9cebb"/><stop offset="1" stop-color="#3b4231"/></linearGradient><radialGradient id="shadow"><stop stop-color="#0a0b08"/><stop offset="1" stop-color="#12140f" stop-opacity="0"/></radialGradient></defs><circle cx="250" cy="250" r="175" fill="url(#shadow)"/>${rings}</svg></div>`}
function header(){return `<a class="skip" href="#main">Skip to content</a><header class="site-header"><a class="brand" href="index.html" aria-label="NHY Artists home">NHY<sup>✳</sup></a><button class="menu-button" aria-expanded="false" aria-controls="navigation">Menu <span aria-hidden="true">☰</span></button><nav class="nav" id="navigation" aria-label="Main navigation"><a href="index.html" ${page==='index'?'class="active" aria-current="page"':''}><small>01</small>Home</a><a href="artists.html" ${['artists','artist'].includes(page)?'class="active" aria-current="page"':''}><small>02</small>Artists</a><a href="about.html" ${page==='about'?'class="active" aria-current="page"':''}><small>03</small>About / Contact</a><a href="bookings.html" class="nav-book ${page==='bookings'?'active':''}" ${page==='bookings'?'aria-current="page"':''}>Build your night <span aria-hidden="true">↗</span></a></nav></header>`}
function footer(cta=true){return `${cta?`<section class="cta-band" data-scene="atmospheric-particles"><div class="eyebrow"><span class="dot"></span> GOOD NIGHTS START WITH A CONVERSATION</div><a class="cta-big" href="bookings.html">Build your night.<span aria-hidden="true">↗</span></a></section>`:''}<footer class="site-footer"><span>© ${new Date().getFullYear()} NHY ARTISTS &nbsp; / &nbsp; INDEPENDENT BY DESIGN.</span><div class="footer-right"><span class="proto-label">CONCEPT PROTOTYPE</span><button class="motion-toggle" aria-pressed="false">Motion: on</button><a href="about.html#direction">ART DIRECTION — 89TH FLOOR ↗</a></div></footer>`}
function home(){return `<section class="home-hero wrap"><div class="hero-top"><div class="eyebrow"><span class="dot"></span> INDEPENDENT ARTISTS. GLOBAL DANCEFLOORS.</div><span class="mono muted">EST. IN EXPERIENCE / BUILT FOR WHAT’S NEXT</span></div><div class="hero-mark"><div class="mega-word" aria-label="NHY">NHY<sup>ARTISTS</sup></div>${sculpture()}<span class="sculpture-caption">FORM / FREQUENCY — 001</span></div><div class="hero-bottom"><h1>Independent minds.<br><span>Shared frequency.</span></h1><div class="hero-intro"><p>A boutique booking agency.<span class="desktop-copy"> Deep roots. Independent thinking.</span></p><a class="button acid arrow" href="artists.html">Discover our artists <span aria-hidden="true">↗</span></a></div></div><div class="hero-foot mono"><span>ARTIST BOOKING & CREATIVE CONNECTION</span><span>ROOTED IN THE UNDERGROUND</span><a href="#selected">EXPLORE ↓</a></div></section><section class="section light" id="selected"><div class="section-head"><div><div class="eyebrow">01 / THE NEXT CONNECTION</div><h2>Selected artists<span style="font-size:.3em;vertical-align:top;margin-left:10px">(03)</span></h2></div><a class="text-link" href="artists.html">Explore the roster <span>↗</span></a></div><div class="featured-gallery"><div class="artist-grid home-artists" id="featured-track" role="region" aria-label="Featured artists — swipe or use arrow keys" tabindex="0">${artists.slice(0,3).map(card).join('')}</div><div class="gallery-controls"><span class="gallery-position" aria-live="polite" aria-atomic="true">01 / 03</span><span class="gallery-hint">SWIPE TO DISCOVER</span><div class="gallery-buttons"><button class="gallery-prev" type="button" aria-label="Previous featured artist" disabled>←</button><button class="gallery-next" type="button" aria-label="Next featured artist">→</button></div></div></div><p class="disclaimer featured-disclaimer">Fictional artists. AI-generated press placeholders.</p><div class="agency-note reveal"><div class="eyebrow">02 / PEOPLE BEFORE EVERYTHING</div><div><p style="font-size:16px;letter-spacing:0;line-height:1.6;max-width:520px">Led by Nick Yates. 20 years in electronic music.</p><a class="text-link" href="about.html">Get to know NHY <span>↗</span></a></div></div></section>`}
function roster(){return `<section class="page-intro"><div class="eyebrow"><span class="dot"></span> THE ROSTER / SIX DISTINCT PERSPECTIVES</div><h1>Individual sounds.<br><span class="muted">Collective energy.</span></h1><div class="intro-row"><p>Different instincts. A shared commitment to the dancefloor. Find your next connection.</p><span class="mono muted">01 — 06 / FICTIONAL ARTIST CONCEPTS</span></div></section><section class="roster-section light"><div class="roster-tools"><label class="search-wrap"><span aria-hidden="true">⌕</span><input id="artist-search" type="search" aria-label="Search artists, genres or cities" placeholder="Search artists, sound or city" autocomplete="off"></label><div class="filters" role="group" aria-label="Filter by genre">${['All sounds','House','Minimal','Techno'].map((v,i)=>`<button class="filter" data-genre="${i?v:''}" aria-pressed="${!i}">${v}</button>`).join('')}</div><div class="view-controls" role="group" aria-label="Roster layout"><button class="view-button" data-view="grid" aria-pressed="true" aria-label="Grid view">▦</button><button class="view-button" data-view="list" aria-pressed="false" aria-label="List view">☰</button></div></div><div class="roster-count"><span id="result-count" role="status">06 ARTISTS</span><span>BOOKING ENQUIRIES OPEN / SAMPLE ROSTER</span></div><div class="artist-grid" id="roster-grid">${artists.map(card).join('')}</div><p class="disclaimer">Fictional names and artist concepts for design purposes only. No representation of real artists is claimed. Press portraits are AI-generated placeholders.</p></section>`}
const wave=()=>`<span class="wave" aria-hidden="true">${Array.from({length:16},(_,i)=>`<i style="--h:${6+(i*13%21)}px;--d:${i*.04}s"></i>`).join('')}</span>`;
function artistPage(){const id=new URLSearchParams(location.search).get('id')||artists[0].id;const a=artists.find(a=>a.id===id);if(!a)return `<section class="page-intro"><h1>Off the record.</h1><p>That sample artist isn’t in this roster.</p><a class="button acid" href="artists.html">Explore the artists ↗</a></section>`;document.title=`${a.name} — NHY Artists`;return `<section class="artist-hero"><a class="back-link" href="artists.html">← BACK TO THE ROSTER</a><div class="artist-layout"><div class="portrait-frame" data-scene="artist-portal">${portrait(a)}<span class="portrait-tag">FICTIONAL ARTIST / PRESS PLACEHOLDER</span></div><div class="artist-title"><div class="eyebrow"><span class="dot"></span> ${a.city} / WORLDWIDE ENQUIRIES</div><h1>${a.name}</h1><div class="tags"><span class="tag">${a.genre}</span><span class="tag">${a.extra}</span></div><p class="lead">${a.line}</p><a class="button acid arrow" href="bookings.html?artist=${a.id}">Enquire for ${a.name}<span>↗</span></a><p class="disclaimer">Fictional artist concept. No real representation implied.</p></div></div></section><section class="artist-body light"><div><div class="eyebrow">01 / THE ARTIST</div><h2>A sound of their own.</h2><p class="body-copy">${a.bio}</p><p class="body-copy">${a.bio2}</p><div class="dates"><div class="eyebrow">SELECTED DATES / ILLUSTRATIVE ONLY</div><div class="date-row"><strong>06 NOV<br>2026</strong><span>Room 04<small><br>LONDON</small></span><small>CLUB</small></div><div class="date-row"><strong>21 NOV<br>2026</strong><span>The Lower Level<small><br>AMSTERDAM</small></span><small>CLUB</small></div><div class="date-row"><strong>12 DEC<br>2026</strong><span>Open Circuit<small><br>BARCELONA</small></span><small>SHOWCASE</small></div><p class="disclaimer">Sample events and venues. These are not announced performances.</p></div></div><div><div class="eyebrow">02 / FIND THE FREQUENCY</div><h2>Step inside the sound.</h2><div class="player"><button class="play" data-track="0" aria-label="Play ${a.mix} demo" aria-pressed="false">▶</button><div class="track-info"><strong>${a.mix}</strong><small>GENERATIVE AUDIO DEMO / 00:30</small></div>${wave()}</div><div class="player"><button class="play" data-track="1" aria-label="Play Room Study demo" aria-pressed="false">▶</button><div class="track-info"><strong>Room Study / live sketch</strong><small>GENERATIVE AUDIO DEMO / 00:30</small></div>${wave()}</div><p class="disclaimer">Interactive sound placeholders generated in your browser. Not recordings or music by a represented artist. Real listening links will replace these.</p><div style="margin-top:55px;border-top:1px solid #b7baac;padding-top:30px"><div class="eyebrow">03 / MAKE THE CONNECTION</div><h2>Your room.<br>Their perspective.</h2><p class="body-copy">Tell us what you have in mind. Start with the artist and we’ll build the brief around your night.</p><a class="button dark arrow" href="bookings.html?artist=${a.id}">Start a booking enquiry <span>↗</span></a></div></div></section>`}
function about(){return `<section class="about-lead"><div class="eyebrow"><span class="dot"></span> THE AGENCY / INDEPENDENT BY DESIGN</div><h1>Built on instinct.<br>Backed by experience.<br><span>Driven by music.</span></h1><div class="about-bottom"><p>A personal approach to artist booking.<br>For the people who make the music.<br>And the people who make it happen.</p><div class="about-seal">NHY ARTISTS<br>20 YEARS<br>IN THE MAKING</div></div></section><section class="about-section light"><div><div class="eyebrow">01 / NICK YATES</div><h2>Deep roots.<br>A fresh perspective.</h2></div><div><p class="body-copy">NHY is a boutique booking agency headed by Nick Yates. With 20 years of experience in electronic music and a background spanning Paradise and Kaluki, Nick brings a deep understanding of the culture, the artists and the rooms that connect them.</p><p class="body-copy">The agency is built around a simple belief: the best connections come from listening. Understanding an artist’s direction. Understanding a promoter’s ambition. Finding the space where both can grow.</p><div class="credential"><span>Industry experience</span><span>20 YEARS</span></div><div class="credential"><span>Industry background</span><span>PARADISE / KALUKI</span></div><div class="credential"><span>Approach</span><span>PERSONAL / INDEPENDENT</span></div></div><div><div class="eyebrow">02 / HOW WE THINK</div><h2>Small by choice.<br>Connected by nature.</h2></div><div class="principles"><div class="principle"><span>01</span><div><h3>Artists, as individuals.</h3><p>Distinct identities deserve considered direction. We start with the person and the music.</p></div></div><div class="principle"><span>02</span><div><h3>The room matters.</h3><p>A booking is more than a name on a line-up. Context, crowd and timing make the difference.</p></div></div><div class="principle"><span>03</span><div><h3>Relationships over transactions.</h3><p>Clear conversations, shared ambition and a long-term view of what we can build together.</p></div></div></div></section><section class="contact-panel" id="contact"><div><div class="eyebrow">03 / GET IN TOUCH</div><h2>Let’s make<br>something happen.</h2><p>Planning a club night, festival or private event? Tell us about the room, the sound and the people you want to bring together.</p></div><div class="contact-actions"><a class="button acid arrow" href="bookings.html">Promoter enquiries <span>↗</span></a><a class="text-link" href="bookings.html?type=private">Start a private enquiry <span>↗</span></a><p class="disclaimer">Contact routing is awaiting agency details. This prototype creates a downloadable enquiry brief; it does not send messages.</p></div></section><section class="contact-panel" id="direction"><div><div class="eyebrow">04 / CREATIVE DIRECTION</div><h2>89th FLOOR.</h2></div><div><p>Art direction for an agency looking forward. Editorial clarity, digital experimentation and an identity built to move with the music.</p><p class="disclaimer">NHY / NHY Artists concept prototype. Fictional roster and AI-generated press placeholders. Nick’s background is based on the supplied project brief.</p></div></section>`}
let booking={step:0,selected:[],recommend:false,type:'Promoter / public event',city:'',venue:'',date:'',flexible:false,budget:'',currency:'GBP',name:'',email:'',company:'',notes:'',consent:false};
function bookings(){const params=new URLSearchParams(location.search);const selected=artists.find(a=>a.id===params.get('artist'));if(selected)booking.selected=[selected.id];if(params.get('type')==='private')booking.type='Private enquiry';return `<section class="booking-shell"><aside class="booking-aside"><div class="eyebrow"><span class="dot"></span> BOOKING ENQUIRIES</div><h1>Build<br>your night.</h1><p>A great night starts with the right connection. Tell us a little about yours.</p><div class="booking-note"><div class="eyebrow">PERSONAL FROM THE FIRST CONVERSATION</div><p>A few details help shape a thoughtful enquiry. Choose an artist, or let the sound lead the way.</p><p>Prototype mode: your brief stays in this browser until you download it. Nothing is sent to the agency.</p></div></aside><div class="booking-panel" id="booking-panel"></div></section>`}
$('#app').innerHTML=header()+`<main id="main" class="page-enter">${({index:home,artists:roster,artist:artistPage,bookings,about}[page]||home)()}</main>`+footer(page!=='bookings');
drawArrowIcons($('#app'));
$('.menu-button').addEventListener('click',()=>{const open=$('.menu-button').getAttribute('aria-expanded')!=='true';$('.menu-button').setAttribute('aria-expanded',open);$('.menu-button').innerHTML=open?'Close <span aria-hidden="true">×</span>':'Menu <span aria-hidden="true">☰</span>';$('.nav').classList.toggle('open',open);document.body.classList.toggle('menu-open',open)});
document.addEventListener('keydown',e=>{if(e.key==='Escape'&&document.body.classList.contains('menu-open')){$('.menu-button').click();$('.menu-button').focus()}});
let motionOff=matchMedia('(prefers-reduced-motion: reduce)').matches;try{motionOff=localStorage.getItem('nhy-motion')==='off'||motionOff}catch{}
function setMotion(){document.documentElement.classList.toggle('no-motion',motionOff);$('.motion-toggle').textContent=`Motion: ${motionOff?'off':'on'}`;$('.motion-toggle').setAttribute('aria-pressed',motionOff)}setMotion();$('.motion-toggle').addEventListener('click',()=>{motionOff=!motionOff;try{localStorage.setItem('nhy-motion',motionOff?'off':'on')}catch{}setMotion()});
if('IntersectionObserver'in window){const obs=new IntersectionObserver(entries=>entries.forEach(e=>{if(e.isIntersecting){e.target.classList.remove('waiting');obs.unobserve(e.target)}}),{threshold:.1});$$('.reveal').forEach(el=>{el.classList.add('waiting');obs.observe(el)})}
if(page==='artists'){let genre='';const update=()=>{const q=$('#artist-search').value.trim().toLowerCase();const shown=artists.filter(a=>(!genre||a.genre===genre)&&`${a.name} ${a.genre} ${a.extra} ${a.city}`.toLowerCase().normalize('NFD').replace(/[\u0300-\u036f]/g,'').includes(q.normalize('NFD').replace(/[\u0300-\u036f]/g,'')));$('#roster-grid').innerHTML=shown.length?shown.map(a=>card(a,artists.indexOf(a))).join(''):'<div class="empty-state"><h2>No artists in this frequency.</h2><p>Try a different sound, name or city.</p><button class="button dark" id="reset-filter">Reset filters ↗</button></div>';$('#result-count').textContent=`${String(shown.length).padStart(2,'0')} ARTIST${shown.length===1?'':'S'}`;drawArrowIcons($('#roster-grid'));$('#reset-filter')?.addEventListener('click',()=>{$('#artist-search').value='';$('.filter').click()})};$('#artist-search').addEventListener('input',update);$$('.filter').forEach(b=>b.addEventListener('click',()=>{genre=b.dataset.genre;$$('.filter').forEach(x=>x.setAttribute('aria-pressed',x===b));update()}));$$('.view-button').forEach(b=>b.addEventListener('click',()=>{$('#roster-grid').classList.toggle('list',b.dataset.view==='list');$$('.view-button').forEach(x=>x.setAttribute('aria-pressed',x===b))}))}
function progress(){return `<div class="progress" aria-label="Enquiry progress">${['The talent','The event','Your details','Review'].map((s,i)=>`<span class="${i===booking.step?'current':i<booking.step?'done':''}" ${i===booking.step?'aria-current="step"':''}>0${i+1}<br>${s}</span>`).join('')}</div>`}
function field(label,name,type='text',required=true,extra=''){return `<label class="field ${extra}">${label}${required?' *':''}<input type="${type}" name="${name}" value="${esc(booking[name])}" ${required?'required':''} ${name==='date'?`min="${localDate()}" ${booking.flexible?'disabled':''}`:''} ${name==='email'?'autocomplete="email"':name==='name'?'autocomplete="name"':name==='company'?'autocomplete="organization"':''} maxlength="${name==='email'?254:120}"></label>`}
function localDate(){const d=new Date();return `${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`}
function selectedNames(){return booking.selected.map(id=>artists.find(a=>a.id===id)?.name).filter(Boolean).join(', ')}
function renderBooking(focus=false){const panel=$('#booking-panel');let content='';
if(booking.step===0){content=`<h2 tabindex="-1">Find your frequency.</h2><p class="form-intro">Choose one or more artists. Or leave room for a recommendation.</p><div class="talent-options">${artists.map(a=>`<label class="talent-option">${portrait(a)}<span><strong>${a.name}</strong><small>${a.genre.toUpperCase()}</small></span><input type="checkbox" name="talent" value="${a.id}" aria-label="Select ${a.name}" ${booking.selected.includes(a.id)?'checked':''}></label>`).join('')}</div><label class="check-label"><input name="recommend" type="checkbox" ${booking.recommend?'checked':''}>I’d like an artist recommendation.</label><p class="disclaimer">Sample artists only. Select any to try the enquiry experience.</p>`}
if(booking.step===1){content=`<h2 tabindex="-1">Set the scene.</h2><p class="form-intro">The room, the moment, the possibilities.</p><p class="required-note">* REQUIRED / APPROXIMATIONS ARE WELCOME</p><div class="field-grid"><label class="field full">Enquiry type *<select name="type"><option ${booking.type==='Promoter / public event'?'selected':''}>Promoter / public event</option><option ${booking.type==='Private enquiry'?'selected':''}>Private enquiry</option></select></label>${field('City / country','city')}${field('Venue / event name','venue')}${field('Preferred date','date','date',!booking.flexible)}<label class="field">Artist fee budget *<select name="budget" required><option value="">Select a range</option>${['Under 2,500','2,500 – 5,000','5,000 – 10,000','10,000 – 25,000','25,000+','Let’s discuss'].map(s=>`<option ${booking.budget===s?'selected':''}>${s}</option>`).join('')}</select></label><label class="field">Currency<select name="currency">${['GBP','EUR','USD'].map(v=>`<option ${booking.currency===v?'selected':''}>${v}</option>`).join('')}</select></label></div><label class="check-label"><input name="flexible" type="checkbox" ${booking.flexible?'checked':''}>Date to be confirmed / flexible</label>`}
if(booking.step===2){content=`<h2 tabindex="-1">Make the introduction.</h2><p class="form-intro">A few details to put a person behind the plan.</p><p class="required-note">* REQUIRED</p><div class="field-grid">${field('Your name','name')}${field('Email address','email','email')}${field('Company / promoter','company','text',false,'full')}<label class="field full">Anything else we should know?<textarea name="notes" maxlength="2000" placeholder="Capacity, musical direction, timings, or your vision for the night…">${esc(booking.notes)}</textarea></label></div><label class="check-label"><input name="consent" type="checkbox" required ${booking.consent?'checked':''}>I understand this is a prototype. My enquiry will not be sent; I can download a copy after reviewing it.</label>`}
if(booking.step===3){content=`<h2 tabindex="-1">One last look.</h2><p class="form-intro">Review your brief. You can change any detail before creating it.</p><div class="review-group"><div class="review-head">01 / THE TALENT <button type="button" data-edit="0">Edit</button></div><p>${esc(selectedNames())}${booking.recommend?(booking.selected.length?'\n':'')+'Artist recommendations welcome':''}</p></div><div class="review-group"><div class="review-head">02 / THE EVENT <button type="button" data-edit="1">Edit</button></div><p>${esc(booking.type)}<br>${esc(booking.venue)} · ${esc(booking.city)}<br>${booking.flexible?'Date flexible / to be confirmed':esc(booking.date)}<br>Artist fee budget: ${esc(booking.budget)} ${booking.budget==='Let’s discuss'?'':booking.currency}</p></div><div class="review-group"><div class="review-head">03 / YOUR DETAILS <button type="button" data-edit="2">Edit</button></div><p>${esc(booking.name)}${booking.company?' · '+esc(booking.company):''}<br>${esc(booking.email)}${booking.notes?'<br><br>'+esc(booking.notes):''}</p></div><p class="disclaimer">Creating a brief does not confirm a booking or send an enquiry.</p>`}
panel.innerHTML=progress()+`<form id="enquiry-form">${content}<div class="form-error" id="form-error" role="alert" hidden></div><div class="form-actions">${booking.step?'<button class="back-button" type="button" id="form-back">← Back</button>':'<span class="mono" style="color:#6d745f;font-size:8px">ABOUT 2 MINUTES</span>'}<button class="button dark arrow" type="submit">${booking.step===3?'Create enquiry brief':'Continue'} <span aria-hidden="true">↗</span></button></div></form>`;
drawArrowIcons(panel);$('#enquiry-form').addEventListener('submit',e=>{e.preventDefault();saveStep();if((booking.step===1&&(!booking.city||!booking.venue))||(booking.step===2&&!booking.name)){$('#form-error').hidden=false;$('#form-error').textContent='Please enter the required details; spaces alone won’t work.';return}if(booking.step===0&&!booking.selected.length&&!booking.recommend){$('#form-error').hidden=false;$('#form-error').textContent='Choose an artist or request a recommendation to continue.';return}if(booking.step===3){showSuccess();return}booking.step++;renderBooking(true)});
$('#form-back')?.addEventListener('click',()=>{saveStep();booking.step--;renderBooking(true)});$$('[data-edit]').forEach(b=>b.addEventListener('click',()=>{booking.step=Number(b.dataset.edit);renderBooking(true)}));$('[name=flexible]')?.addEventListener('change',e=>{const date=$('[name=date]');date.disabled=e.target.checked;date.required=!e.target.checked});if(focus){$('h2',panel).focus({preventScroll:true});panel.scrollIntoView({behavior:motionOff?'instant':'smooth',block:'start'})}}
function saveStep(){const form=$('#enquiry-form');const data=new FormData(form);if(booking.step===0){booking.selected=data.getAll('talent');booking.recommend=data.has('recommend')}if(booking.step===1){for(const k of ['type','city','venue','budget','currency'])booking[k]=String(data.get(k)||'').trim();booking.flexible=data.has('flexible');if(!booking.flexible)booking.date=data.get('date')||''}if(booking.step===2){for(const k of ['name','email','company','notes'])booking[k]=String(data.get(k)||'').trim();booking.consent=data.has('consent')}}
function brief(){return `NHY ARTISTS / ENQUIRY BRIEF\nPROTOTYPE — NOT SENT / NO BOOKING CONFIRMED\n\nTALENT\n${selectedNames()||'Recommendation requested'}${booking.recommend?'\nArtist recommendations welcome':''}\n\nEVENT\nType: ${booking.type}\nCity: ${booking.city}\nVenue: ${booking.venue}\nDate: ${booking.flexible?'Flexible / to be confirmed':booking.date}\nArtist fee budget: ${booking.budget} ${booking.budget==='Let’s discuss'?'':booking.currency}\n\nCONTACT\nName: ${booking.name}\nEmail: ${booking.email}\nCompany: ${booking.company||'—'}\n\nNOTES\n${booking.notes||'—'}\n\nAll roster artists are fictional prototype content. No enquiry has been sent.`}
function showSuccess(){const panel=$('#booking-panel');panel.innerHTML=`<div class="success"><div class="eyebrow">YOUR NIGHT / STARTS HERE</div><div class="success-mark" aria-hidden="true">✓</div><h2 tabindex="-1">Your brief is ready.</h2><p>Thanks, ${esc(booking.name.split(' ')[0])}. Your enquiry brief is ready to download and share when agency contact details are confirmed.</p><p><strong>Nothing has been sent. This is a prototype, and no booking is confirmed.</strong></p><button class="button dark arrow" id="download-brief">Download your brief <span>↓</span></button><div><button class="back-button" id="review-again">← Back to your brief</button></div><p class="disclaimer">Your contact details are kept in page memory only. Reloading or leaving this page clears the draft.</p></div>`;drawArrowIcons(panel);$('#download-brief').addEventListener('click',()=>{const url=URL.createObjectURL(new Blob([brief()],{type:'text/plain;charset=utf-8'}));const a=document.createElement('a');a.href=url;a.download='NHY-enquiry-brief.txt';a.click();setTimeout(()=>URL.revokeObjectURL(url),2000)});$('#review-again').addEventListener('click',()=>renderBooking(true));$('h2',panel).focus({preventScroll:true});panel.scrollIntoView({behavior:motionOff?'instant':'smooth',block:'start'})}
if(page==='bookings')renderBooking();
let audioCtx=null,audioTimer=null,activeTrack=null;
function stopAudio(){clearInterval(audioTimer);audioTimer=null;if(audioCtx){audioCtx.close();audioCtx=null}$$('.play').forEach(b=>{b.textContent='▶';b.setAttribute('aria-pressed','false');b.closest('.player').classList.remove('playing')});activeTrack=null}
function tone(ctx,freq,start,duration,volume,type='sine'){const o=ctx.createOscillator(),g=ctx.createGain();o.type=type;o.frequency.setValueAtTime(freq,start);g.gain.setValueAtTime(.0001,start);g.gain.exponentialRampToValueAtTime(volume,start+.006);g.gain.exponentialRampToValueAtTime(.0001,start+duration);o.connect(g);g.connect(ctx.destination);o.start(start);o.stop(start+duration+.02)}
$$('.play').forEach(btn=>btn.addEventListener('click',async()=>{const track=Number(btn.dataset.track);if(activeTrack===track){stopAudio();return}stopAudio();try{audioCtx=new(window.AudioContext||window.webkitAudioContext)();await audioCtx.resume();activeTrack=track;btn.textContent='Ⅱ';btn.setAttribute('aria-pressed','true');btn.closest('.player').classList.add('playing');const ctx=audioCtx,bpm=track?128:118,step=60/bpm/4;let n=0,next=ctx.currentTime+.05;const end=next+30;audioTimer=setInterval(()=>{if(ctx.state==='closed')return;while(next<ctx.currentTime+.15&&next<end){if(n%4===0){const o=ctx.createOscillator(),g=ctx.createGain();o.frequency.setValueAtTime(140,next);o.frequency.exponentialRampToValueAtTime(42,next+.15);g.gain.setValueAtTime(.16,next);g.gain.exponentialRampToValueAtTime(.0001,next+.23);o.connect(g);g.connect(ctx.destination);o.start(next);o.stop(next+.25)}if(n%2===1)tone(ctx,track?6100:7100,next,.025,.012,'square');if(n%8===3||n%8===6)tone(ctx,[55,65.41,73.42,49][Math.floor(n/16)%4],next,.19,.07,'triangle');if(n%16===10)tone(ctx,track?440:329.63,next,.45,.022);n++;next+=step}if(ctx.currentTime>end)stopAudio()},40)}catch{stopAudio();const p=document.createElement('p');p.className='disclaimer';p.textContent='Audio is unavailable in this browser.';btn.closest('.player').after(p)}}));
window.addEventListener('pagehide',stopAudio);document.addEventListener('visibilitychange',()=>{if(document.hidden)stopAudio()});
