if(page==='index'){
  const track=$('#featured-track'),prev=$('.gallery-prev'),next=$('.gallery-next'),position=$('.gallery-position');
  const mobile=matchMedia('(max-width: 700px)');
  let frame=0;
  const activeIndex=()=>Math.max(0,Math.min(2,Math.round(track.scrollLeft/track.clientWidth)));
  const update=()=>{frame=0;const i=activeIndex();position.textContent=`${String(i+1).padStart(2,'0')} / 03`;prev.disabled=i===0;next.disabled=i===2};
  const move=delta=>{if(!mobile.matches)return;const i=Math.max(0,Math.min(2,activeIndex()+delta));track.scrollTo({left:i*track.clientWidth,behavior:motionOff?'instant':'smooth'})};
  prev.addEventListener('click',()=>move(-1));next.addEventListener('click',()=>move(1));
  track.addEventListener('scroll',()=>{if(!frame)frame=requestAnimationFrame(update)},{passive:true});
  track.addEventListener('keydown',e=>{if(mobile.matches&&(e.key==='ArrowRight'||e.key==='ArrowLeft')){e.preventDefault();move(e.key==='ArrowRight'?1:-1)}});
  track.addEventListener('focusin',e=>{const card=e.target.closest('.artist-card');if(card&&mobile.matches)track.scrollTo({left:[...track.children].indexOf(card)*track.clientWidth,behavior:'instant'})});
  window.addEventListener('resize',update);update();
}
